#
# 01-Install-ADDSForest.ps1
# Promotes DC01 to the first domain controller of a new forest: lab.local
#
# Generated by the AD DS Configuration Wizard ("View script" on Review Options),
# then saved here so the GUI deployment can be reproduced with PowerShell.
#
# Prerequisites (already done on DC01):
#   - Static IP 10.0.10.10/24, gateway 10.0.10.1, DNS 127.0.0.1
#   - Computer renamed to DC01
#   - Install-WindowsFeature AD-Domain-Services -IncludeManagementTools
#
# When run, PowerShell prompts for the DSRM (SafeModeAdministratorPassword).
# No passwords are stored in this file.
#

Import-Module ADDSDeployment
Install-ADDSForest `
-CreateDnsDelegation:$false `
-DatabasePath "C:\WINDOWS\NTDS" `
-DomainMode "Win2025" `
-DomainName "lab.local" `
-DomainNetbiosName "LAB" `
-ForestMode "Win2025" `
-InstallDns:$true `
-LogPath "C:\WINDOWS\NTDS" `
-NoRebootOnCompletion:$false `
-SysvolPath "C:\WINDOWS\SYSVOL" `
-Force:$true
